(() => {
	"use strict";
	const KEY = "edreamscars_saved_posts_v1";
	let toastEl = null;
	let toastTimer = null;
	function ensureToast() {
		if (toastEl) return toastEl;
		toastEl = document.getElementById("toast");
		if (!toastEl) {
			toastEl = document.createElement("div");
			toastEl.id = "toast";
			toastEl.className = "toast";
			toastEl.setAttribute("role", "status");
			toastEl.setAttribute("aria-live", "polite");
			toastEl.setAttribute("aria-atomic", "true");
			document.body.appendChild(toastEl);
		}
		return toastEl;
	}
	function toast(msg) {
		const el = ensureToast();
		el.textContent = msg;
		el.classList.add("is-visible");
		window.clearTimeout(toastTimer);
		toastTimer = window.setTimeout(
			() => el.classList.remove("is-visible"),
			1400,
		);
	}
	function safeParse(json, fallback) {
		try {
			return JSON.parse(json);
		} catch {
			return fallback;
		}
	}
	function storageAvailable() {
		try {
			const x = "__t__";
			localStorage.setItem(x, x);
			localStorage.removeItem(x);
			return true;
		} catch {
			return false;
		}
	}
	function getSaved() {
		if (!storageAvailable()) return [];
		const raw = localStorage.getItem(KEY);
		const arr = safeParse(raw, []);
		return Array.isArray(arr) ? arr : [];
	}
	function setSaved(arr) {
		if (!storageAvailable()) return;
		localStorage.setItem(KEY, JSON.stringify(arr));
	}
	function setBtnState(btn, pressed) {
		btn.classList.toggle("is-active", pressed);
		btn.classList.toggle("is-saved", pressed);
		btn.setAttribute("aria-pressed", pressed ? "true" : "false");
	}
	function hydrateSaveButtons() {
		const saved = new Set(getSaved().map(String));
		document
			.querySelectorAll('button[data-action="save"][data-id]')
			.forEach((btn) => {
				const id = btn.getAttribute("data-id");
				setBtnState(btn, saved.has(String(id)));
			});
	}
	function initNewsletterFloatingLabels() {
		document
			.querySelectorAll(
				".panel--subscribe .wpcf7-form label input[type='email']",
			)
			.forEach((input) => {
				const label = input.closest("label");
				if (!label) return;
				input.setAttribute("placeholder", " ");
				const sync = () => {
					label.classList.toggle("has-value", input.value.trim() !== "");
				};
				input.addEventListener("input", sync);
				input.addEventListener("blur", sync);
				sync();
			});
	}
	function initNewsletterTips() {
		document.querySelectorAll("[data-tip-toggle]").forEach((btn) => {
			const id = btn.getAttribute("aria-controls");
			if (!id) return;
			const tip = document.getElementById(id);
			if (!tip) return;
			btn.addEventListener("click", () => {
				const expanded = btn.getAttribute("aria-expanded") === "true";
				btn.setAttribute("aria-expanded", expanded ? "false" : "true");
				tip.hidden = expanded;
			});
		});
	}
	function initPostToc() {
		const tocList = document.getElementById("post-toc-list");
		const content = document.querySelector(".post-card .entry-content");
		const tocContainerElement = document.getElementById("toc-container");
		const tocToggle = tocContainerElement?.querySelector(".toc-container__toggle");
		const tocContent = tocContainerElement?.querySelector(".toc-container__content");
		const tocToggleText = tocToggle?.querySelector(".toc-container__text");
		if (!tocList || !content || !tocContainerElement || !tocToggle || !tocContent) return;
		const headings = content.querySelectorAll("h2, h3");
		let sourceNodes = Array.from(headings);
		if (!sourceNodes.length) {
			const pseudoHeadings = content.querySelectorAll("p > strong:first-child");
			sourceNodes = Array.from(pseudoHeadings).map((el) => el.parentElement).filter(Boolean);
		}
		const setTocOpenState = (isOpen) => {
			tocContainerElement.classList.toggle("open", isOpen);
			tocContent.classList.toggle("show", isOpen);
			tocContent.classList.toggle("hidden", !isOpen);
			tocToggle.setAttribute("aria-expanded", isOpen ? "true" : "false");
			if (tocToggleText) {
				tocToggleText.textContent = isOpen
					? "Ocultar tabla de contenidos"
					: "Mostrar tabla de contenidos";
			}
		};
		if (!sourceNodes.length) {
			tocContainerElement.hidden = true;
			return;
		}
		sourceNodes.forEach((heading, index) => {
			const isSubheading = heading.tagName.toLowerCase() === "h3";
			if (!heading.id) {
				heading.id = `toc-heading-${index + 1}`;
			}
			const li = document.createElement("li");
			li.className = isSubheading ? "toc__item toc__item--subitem" : "toc__item";
			const a = document.createElement("a");
			a.className = "toc__link";
			a.href = `#${heading.id}`;
			const number = document.createElement("span");
			number.className = "toc__number";
			number.textContent = `${index + 1}.`;
			a.appendChild(number);
			a.append(` ${heading.textContent?.trim() || `Sección ${index + 1}`}`);
			li.appendChild(a);
			tocList.appendChild(li);
		});
		const isInitiallyOpen = tocToggle.getAttribute("aria-expanded") === "true";
		setTocOpenState(isInitiallyOpen);
		tocToggle.addEventListener("click", () => {
			const isOpen = tocContainerElement.classList.contains("open");
			setTocOpenState(!isOpen);
		});
		tocList.addEventListener("click", (event) => {
			const link = event.target.closest(".toc__link");
			if (!link) return;
			if (window.matchMedia("(max-width: 1279px)").matches) {
				setTocOpenState(false);
			}
		});
	}
	async function shareUrl(url, title) {
		const u = url || window.location.href;
		const t = title || document.title || "EdreamsCars";
		if (navigator.share) {
			try {
				await navigator.share({ title: t, url: u });
				toast("Compartido");
				return;
			} catch {}
		}
		if (navigator.clipboard && window.isSecureContext) {
			try {
				await navigator.clipboard.writeText(u);
				toast("Enlace copiado");
				return;
			} catch {}
		}
		// Fallback muy básico
		prompt("Copia este enlace:", u);
	}
	async function copyCurrentUrl() {
		const u = window.location.href;
		if (navigator.clipboard && window.isSecureContext) {
			try {
				await navigator.clipboard.writeText(u);
				toast("Enlace copiado");
				return;
			} catch {}
		}
		prompt("Copia este enlace:", u);
	}
	// Init
	hydrateSaveButtons();
	initNewsletterFloatingLabels();
	initNewsletterTips();
	initPostToc();
	// Delegación global (archive)
	document.addEventListener("click", async (e) => {
		const btn = e.target.closest("[data-action]");
		if (!btn) return;
		const action = btn.getAttribute("data-action");
		if (action === "save") {
			const id = btn.getAttribute("data-id");
			if (!id) return;
			const saved = getSaved().map(String);
			const idx = saved.indexOf(String(id));
			if (idx >= 0) {
				saved.splice(idx, 1);
				setSaved(saved);
				setBtnState(btn, false);
				toast("Eliminado de guardados");
			} else {
				saved.unshift(String(id));
				setSaved(saved);
				setBtnState(btn, true);
				toast("Guardado");
			}
			return;
		}
		if (action === "share") {
			const url = btn.getAttribute("data-url") || window.location.href;
			await shareUrl(url, document.title);
			return;
		}
		if (action === "copy") {
			await copyCurrentUrl();
			return;
		}
	});
	// Compat single.php actual (si aún tienes ids)
	const copyBtn = document.getElementById("copy-button");
	if (copyBtn) {
		copyBtn.addEventListener("click", (e) => {
			e.preventDefault();
			copyCurrentUrl();
		});
	}
	const shareBtn = document.getElementById("share-button");
	if (shareBtn) {
		shareBtn.addEventListener("click", (e) => {
			e.preventDefault();
			shareUrl(window.location.href, document.title);
		});
	}
})();